(()=>{
const icon=(id)=>`<svg class="icon" aria-hidden="true"><use href="#ic-${id}"/></svg>`;
const overview=document.querySelector('.war-console');
overview.innerHTML=`<div class="orbital-heading"><span>企業系統聯動</span><span>INTERACTIVE ARCHITECTURE</span></div><div class="orbital-scene"><div class="orbital-stars"></div><svg viewBox="0 0 600 390" class="orbital-svg" aria-hidden="true"><defs><radialGradient id="orbital-aura"><stop stop-color="#3bbde5" stop-opacity=".32"/><stop offset="1" stop-color="#1f91d4" stop-opacity="0"/></radialGradient><linearGradient id="orbital-metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#b8f1ff"/><stop offset=".5" stop-color="#205b91"/><stop offset="1" stop-color="#7ac8f4"/></linearGradient></defs><ellipse cx="300" cy="225" rx="210" ry="145" fill="url(#orbital-aura)"/><g class="orbital-rings" fill="none" stroke="#57b9e0"><ellipse cx="300" cy="215" rx="200" ry="79" opacity=".35"/><ellipse cx="300" cy="215" rx="160" ry="58" opacity=".5" stroke-dasharray="4 7"/><ellipse cx="300" cy="215" rx="225" ry="100" opacity=".25" stroke-dasharray="1 8"/></g><g class="orbital-links" fill="none" stroke="#69d9fa"><path d="M105 105 300 200 495 105M105 295 300 200 495 295"/></g><g class="orbital-wire" transform="translate(300 190)" fill="none" stroke="#76dcf6" stroke-width=".7"><circle r="78"/><ellipse rx="78" ry="28"/><ellipse rx="78" ry="55"/><ellipse rx="30" ry="78"/><ellipse rx="55" ry="78"/><path d="M-78 0H78M0-78V78"/></g><path d="m300 267 84 40-84 40-84-40Z" fill="#073052" stroke="#458db3"/><path d="m300 252 84 40-84 40-84-40Z" fill="#12537b" stroke="#83dbf0"/><path d="m300 236 84 40-84 40-84-40Z" fill="url(#orbital-metal)" stroke="#a3f0ff"/><circle cx="300" cy="190" r="53" fill="#08283e" fill-opacity=".8" stroke="#a5edff"/><image href="assets/f-mark.svg" x="265" y="151" width="70" height="70"/><g class="orbital-traffic" fill="#b5f4ff"><circle r="4"><animateMotion dur="5s" repeatCount="indefinite" path="M105 105 300 200 495 295"/></circle><circle r="3"><animateMotion dur="6s" repeatCount="indefinite" path="M495 105 300 200 105 295"/></circle></g></svg>${[['target','經營策略'],['signal','品牌獲客'],['flow','營運流程'],['spark','AI 應用']].map((n,i)=>`<button class="orbital-node orbital-node-${i}" data-orbital="${i}" aria-pressed="${i===0}">${icon(n[0])}<span>${n[1]}</span></button>`).join('')}<span class="orbital-caption">CONNECT THE BUSINESS</span></div><div class="orbital-readout" aria-live="polite"><span id="orbital-number">01 / STRATEGY</span><p id="orbital-copy">釐清經營目標，把資源集中在優先問題。</p></div><div class="orbital-mode"><span>架構示意 · 點選四個節點探索</span><a href="#solutions">查看解決方案</a></div>`;
const copy=[['01 / STRATEGY','釐清經營目標，把資源集中在優先問題。'],['02 / GROWTH','串接內容、官網與名單，追蹤從曝光到詢問。'],['03 / OPERATIONS','整合資料、權責與回報，讓流程可以持續運作。'],['04 / AI ENABLEMENT','把 AI 接進工作流程，保留人工覆核與交接。']];overview.querySelectorAll('[data-orbital]').forEach(b=>b.onclick=()=>{overview.querySelectorAll('[data-orbital]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let d=copy[+b.dataset.orbital];document.getElementById('orbital-number').textContent=d[0];document.getElementById('orbital-copy').textContent=d[1]});
const diagrams=[['履歷來源','欄位整理','面試判讀','招募追蹤'],['品牌內容','管道整合','詢問分流','轉換追蹤'],['表單資料','規則處理','人工覆核','管理追蹤'],['經營問題','優先排序','權責決策','行動追蹤']];
let sequence=0;
function createFlow(labels,mode){const id='flow-'+(++sequence);const el=document.createElement('div');el.className='flow-visual';el.dataset.state='after';el.dataset.running='false';el.innerHTML=`<div class="flow-controls"><div role="group" aria-label="流程比較"><button data-flow-state="before" aria-pressed="false">導入前</button><button data-flow-state="after" aria-pressed="true">方案設計</button></div><button class="flow-play" type="button">播放流程</button></div><div class="flow-drawing"><svg class="flow-connections" viewBox="0 0 600 170" preserveAspectRatio="none" aria-hidden="true"><path class="flow-order" d="M65 85H535"/><path class="flow-chaos" d="M65 85 220 30 380 140 535 85M65 85 380 35 220 140 535 85M220 30V140"/><path class="flow-packet" d="M65 85H535"/></svg><div class="flow-stages">${labels.map((s,i)=>`<button class="flow-stage" data-stage="${i}" aria-pressed="false"><span class="flow-plate">${icon(['people','flow','target','chart'][i])}<i>0${i+1}</i></span><b>${s}</b><small>${['INPUT','ORGANIZE','REVIEW','ACTION'][i]}</small></button>`).join('')}</div><span class="flow-disconnect">資料與責任尚未串接</span></div><div class="flow-message" aria-live="polite"><i></i><span>方案示意：串接工作流程，保留人工判讀。</span></div>`;
let timer=null,at=-1;function stop(){clearTimeout(timer);el.dataset.running='false';el.querySelector('.flow-play').textContent='播放流程'}function stage(n){at=n;el.querySelectorAll('[data-stage]').forEach((b,j)=>{b.classList.toggle('visited',j<=n);b.setAttribute('aria-pressed',String(j===n))});el.querySelector('.flow-message span').textContent=[`01｜${labels[0]}：確認資料來源與基本欄位。`,`02｜${labels[1]}：以一致規則整理資訊。`,`03｜${labels[2]}：由負責人確認例外與判斷。`,`04｜${labels[3]}：追蹤進度與結果，形成改善依據。`][n]}
el.querySelectorAll('[data-flow-state]').forEach(b=>b.onclick=()=>{stop();el.dataset.state=b.dataset.flowState;el.querySelectorAll('[data-flow-state]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));el.querySelector('.flow-play').disabled=b.dataset.flowState==='before';el.querySelector('.flow-message span').textContent=b.dataset.flowState==='before'?'常見斷點：資料分散、反覆轉交、進度難追蹤。':'方案示意：串接工作流程，保留人工判讀。';el.querySelectorAll('[data-stage]').forEach(x=>{x.classList.remove('visited');x.setAttribute('aria-pressed','false')})});
el.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{if(el.dataset.state==='before')return;stop();stage(+b.dataset.stage)});
el.querySelector('.flow-play').onclick=()=>{if(el.dataset.running==='true'){stop();return}el.dataset.running='true';el.querySelector('.flow-play').textContent='暫停演示';at=-1;function next(){if(!el.isConnected){stop();return}if(document.body.classList.contains('motion-off')){stop();return}stage(++at);if(at<3)timer=setTimeout(next,1100);else{stop();el.querySelector('.flow-play').textContent='重新播放'}}next()};
return el}
function installSolution(){const p=document.getElementById('solution-panel');if(p.querySelector('.flow-visual'))return;const selected=+document.querySelector('[data-solution].active').dataset.solution;const visual=createFlow(diagrams[selected]);p.querySelector('h3').after(visual);const step=p.querySelector('.solution-steps');const intro=p.querySelector(':scope > p');const detail=document.createElement('details');detail.className='flow-details';detail.innerHTML='<summary>查看方案內容與交付細節</summary>';if(intro)detail.appendChild(intro);detail.appendChild(step);p.querySelector('.solution-metric').before(detail)}
const sp=document.getElementById('solution-panel');new MutationObserver(installSolution).observe(sp,{childList:true});installSolution();
function installDashboard(){const p=document.getElementById('intel-panel');if(p.querySelector('.visual-simulation'))return;const layout=p.querySelector('.nexus-layout'),lenses=p.querySelector('.nexus-lenses');if(!layout||!lenses)return;const simulation=document.createElement('article');simulation.className='visual-simulation';simulation.innerHTML='<div class="chart-head"><h3>資料到決策的運作演示</h3><span>WORKFLOW SIMULATOR</span></div>';const current=+document.querySelector('[data-intel][aria-selected="true"]').dataset.intel;const l=[diagrams[0],diagrams[1],['市場資料','假設整理','風險判讀','試點追蹤'],['網站內容','流量來源','詢問判讀','轉換追蹤'],diagrams[2]][current];simulation.appendChild(createFlow(l));layout.appendChild(simulation);const button=document.createElement('button');button.dataset.lens='simulation';button.setAttribute('aria-pressed','false');button.textContent='流程演示';lenses.appendChild(button);button.onclick=()=>{layout.dataset.lens='simulation';lenses.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)))};
// Four orbiting signal points and transparent transmission layers add depth to the existing map.
const map=p.querySelector('.map-stage');map.insertAdjacentHTML('afterbegin','<div class="signal-orbit signal-orbit-a" aria-hidden="true"><i></i></div><div class="signal-orbit signal-orbit-b" aria-hidden="true"><i></i></div><div class="map-scan" aria-hidden="true"></div>');
p.querySelectorAll('.nexus-funnel svg').forEach((svg,i)=>{svg.classList.add('animated-funnel');svg.style.setProperty('--delay',i*.35+'s')});}
const dp=document.getElementById('intel-panel');new MutationObserver(installDashboard).observe(dp,{childList:true});installDashboard();
// Three compact moving illustrations replace empty shortcut decoration.
document.querySelectorAll('.overview-shortcuts>a').forEach((a,i)=>{const art=document.createElement('div');art.className='shortcut-art';art.setAttribute('aria-hidden','true');art.innerHTML=[`<svg viewBox="0 0 110 80"><path d="M6 65H104M10 10V65"/><path class="shortcut-line" d="M12 55 32 40 48 48 69 22 88 29 102 12"/><circle cx="69" cy="22" r="5"/></svg>`,`<svg viewBox="0 0 110 80"><path class="shortcut-dash" d="M15 25H55V55H95"/><rect x="5" y="15" width="20" height="20" rx="3"/><rect x="45" y="15" width="20" height="20" rx="3"/><rect x="85" y="45" width="20" height="20" rx="3"/></svg>`,`<svg viewBox="0 0 110 80"><path d="m55 8 40 23-40 23L15 31Z"/><path class="shortcut-layer" d="m55 27 40 23-40 23L15 50Z"/><path d="m43 30 8 7 17-16"/></svg>`][i];a.appendChild(art);a.querySelector(':scope > .icon')?.remove()});
})();
